import{J as e,dt as t,j as n,q as r}from"./chunks/framework.767A_6fc.js";import"./chunks/assets.Dg-KBxrH.js";var i=JSON.parse(`{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1782390088000}`),a={name:`guide/faq.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h1><h3 id="_1-找不到签到入口-怎么办" tabindex="-1">1. 找不到签到入口，怎么办？ <a class="header-anchor" href="#_1-找不到签到入口-怎么办" aria-label="Permalink to “1. 找不到签到入口，怎么办？”">​</a></h3><p>滑动首页功能按钮，最右侧有个设置，把 <strong>爱学习</strong> 打开，首页就可以看到 <strong>爱学习</strong> 了。</p><img src="/image/guide/%E7%AD%BE%E5%88%B0%E5%85%A5%E5%8F%A3.png" style="width:min(15vw, 240px);"><h3 id="_2-账号密码错误-怎么办" tabindex="-1">2. 账号密码错误，怎么办？ <a class="header-anchor" href="#_2-账号密码错误-怎么办" aria-label="Permalink to “2. 账号密码错误，怎么办？”">​</a></h3><ul><li>不确定密码，请前往 <a href="https://i.chaoxing.com" target="_blank" rel="noreferrer">学习通官网</a> 上修改密码。</li><li>密码是正确的但是一直无法登录，检查是否有特殊符号（如 <code>&amp; # ? ^ = +</code> 等），如果有请前往学习通修改密码。</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">警告</p><p>登录失败10次，会被学习通封禁账号15分钟，请不要频繁的登录操作。</p></div><h3 id="_3-人脸识别签到怎么办" tabindex="-1">3. 人脸识别签到怎么办？ <a class="header-anchor" href="#_3-人脸识别签到怎么办" aria-label="Permalink to “3. 人脸识别签到怎么办？”">​</a></h3><p>需要在 <strong>进阶设置</strong> -&gt; <strong>差异化配置</strong> 里配置你的人脸照片。然后才能正常完成签到。</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">提示</p><p>人脸照片（帅照）在请人代签时不会自动携带，需要 TA 手动配置帅照哦~</p></div><h3 id="_4-我登录了很多账号-能不能一次性绑定到其他手机" tabindex="-1">4. 我登录了很多账号，能不能一次性绑定到其他手机？ <a class="header-anchor" href="#_4-我登录了很多账号-能不能一次性绑定到其他手机" aria-label="Permalink to “4. 我登录了很多账号，能不能一次性绑定到其他手机？”">​</a></h3><p>可以的。在 <code>v4.2026.06.25</code> 之后的版本，<strong>进阶设置</strong> 里支持 <strong>备份与恢复</strong>。 你可以输入你的 GitHub 个人访问令牌，将数据上传到 GitHub 账号，然后恢复到任意设备。</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">提示</p><p>备份的小程序和恢复的小程序版本号必须一致哦~</p></div><h3 id="_5-怎么请人代签" tabindex="-1">5. 怎么请人代签？ <a class="header-anchor" href="#_5-怎么请人代签" aria-label="Permalink to “5. 怎么请人代签？”">​</a></h3><p>目前建议直接在 TA 手机上登录学习通账号。但紧急情况可以用转发的方式。</p>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};